$nu = @{}; foreach ($f in $lage['1.0.46'].Keys) { $nu[$f] = Norm (Las $f) }
$h = @{}; foreach ($f in $nu.Keys) { $h[$f] = Hash $nu[$f] }
$egna = @{}
foreach ($f in $h.Keys) { $traff = $false; foreach ($v in $utgavor) { if ($h[$f] -eq $lage[$v][$f]) { $traff = $true; break } }; if (-not $traff -and $h[$f] -ne 'saknas') { $egna[$f] = $true } }
$start = $null
for ($k = $utgavor.Count - 1; $k -ge 0; $k--) {
    $v = $utgavor[$k]; $ok = $true
    foreach ($f in $lage[$v].Keys) { if (-not $egna.ContainsKey($f) -and $h[$f] -ne $lage[$v][$f]) { $ok = $false; break } }
    if ($ok) { $start = $k; break }
}
if ($egna.Count -and $start -ne $null) { Write-Host ('Dina egna versioner (behalls, stegen gors i dem): ' + (($egna.Keys | Sort-Object) -join ', ')) }
$olika = @($lage['1.0.46'].Keys | Sort-Object | Where-Object { $h[$_] -ne $lage['1.0.46'][$_] })
if ($Visa) {
    foreach ($f in $olika) {
        $din = @(if ($nu[$f] -ne $null) { $nu[$f] -split "`n" | ForEach-Object { $_.TrimEnd() } })
        $sid = @(if ($sida14[$f]) { (Txt $sida14[$f]) -split "`n" | ForEach-Object { $_.TrimEnd() } })
        $d = @(Compare-Object $din $sid)
        Write-Host "== $f  (bara hos dig: $(@($d | Where-Object SideIndicator -eq '<=').Count) rader, bara pa sidan: $(@($d | Where-Object SideIndicator -eq '=>').Count) rader)"
        $d | Select-Object -First 12 | ForEach-Object { if ($_.SideIndicator -eq '<=') { "  din:   $($_.InputObject)" } else { "  sidan: $($_.InputObject)" } }
    }
    exit 0
}
if ($start -eq $null -and $SidanFore) {
    $kopia14 = Join-Path $env:TEMP ('spektro-fore-sidan14-' + (Get-Date -Format 'yyyyMMdd-HHmmss'))
    foreach ($f in $olika) {
        $p = Join-Path $Rot $f
        if (Test-Path -LiteralPath $p) { $b = Join-Path $kopia14 $f; New-Item -ItemType Directory -Force (Split-Path $b) | Out-Null; Copy-Item -LiteralPath $p $b }
        $nu[$f] = if ($sida14[$f]) { Norm (Txt $sida14[$f]) } else { $null }
        Write-Host "  sidans version efter 1.0.46: $f"
    }
    Write-Host "Dina versioner av dem: $kopia14"
    $start = 0
}
if ($start -eq $null) {
    Write-Host 'Filerna stammer inte exakt med sidan efter nagon utgava 1.0.46-1.2.12. De som skiljer fran laget efter 1.0.46:'
    $olika | ForEach-Object { Write-Host "  $_" }
    Write-Host 'Se skillnaderna:              powershell -ExecutionPolicy Bypass -File .\spektro-1.1.0-1.2.12.ps1 -Visa'
    Write-Host 'Ta sidans version och fortsatt: powershell -ExecutionPolicy Bypass -File .\spektro-1.1.0-1.2.12.ps1 -SidanFore'
    Write-Host 'Forsoker anda fran 1.1.0 (inget skrivs om ett steg inte gar igenom).'
    $start = 0
} else { Write-Host "Projektet ar som sidan efter $($utgavor[$start])." }
$fore = $utgavor[$start]; $gjorda = 0; $missade = @()
# Filer som ar sidans version (inte egna): direkt till sidans version efter 1.2.12.
foreach ($f in @($nu.Keys)) {
    if ($egna.ContainsKey($f)) { continue }
    $mal = if ($slut[$f]) { Norm (Txt $slut[$f]) } else { $null }
    if ($mal -ne $null -and $nu[$f] -cne $mal) { $nu[$f] = $mal; $gjorda++ }
}
function Los([string]$t, [string]$gammal) {
    # Samma text men blanktecken och tecken utanfor ASCII (a, a, o med prickar) far skilja.
    $sb = New-Object System.Text.StringBuilder
    $ws = $false
    foreach ($ch in $gammal.ToCharArray()) {
        if ($ch -eq [char]10) { [void]$sb.Append('[ \t]*\n'); $ws = $false; continue }
        if ([char]::IsWhiteSpace($ch)) { if (-not $ws) { [void]$sb.Append('[ \t]*') }; $ws = $true; continue }
        $ws = $false
        if ([int]$ch -gt 127) { [void]$sb.Append('[^\x00-\x7F]{1,3}') } else { [void]$sb.Append([regex]::Escape([string]$ch)) }
    }
    return [regex]::Matches($t, $sb.ToString())
}
foreach ($r in $steg) {
    $v, $n, $fil, $typ, $g64, $n64 = $r
    if (-not $egna.ContainsKey($fil)) { continue }
    $ny = Norm (Txt $n64); $t = $nu[$fil]; $namn = "$v steg $n ($typ $fil)"
    if ($typ -eq 'byt') {
        $gammal = Norm (Txt $g64)
        if ($t -eq $null) { $missade += "$namn (filen finns inte)"; continue }
        if ((Antal $t $gammal) -eq 0 -and $t.Contains($ny)) { continue }
        $c = Antal $t $gammal
        if ($c -eq 1) {
            $i = $t.IndexOf($gammal, [StringComparison]::Ordinal); $t = $t.Substring(0, $i) + $ny + $t.Substring($i + $gammal.Length)
        } else {
            $m = Los $t $gammal
            if ($m.Count -ne 1) { $missade += "$namn (texten finns $($m.Count) ganger)"; continue }
            $t = $t.Substring(0, $m[0].Index) + $ny + $t.Substring($m[0].Index + $m[0].Length)
        }
    } elseif ($typ -eq 'lagg_till') {
        if ($t -ne $null -and $ny.Trim() -ne '' -and $t.Contains($ny.Trim())) { continue }
        if ($t -eq $null) { $t = '' }
        if ($t -ne '' -and -not $t.EndsWith("`n")) { $t += "`n" }
        $t += $ny
    } else { $t = $ny }
    $nu[$fil] = $t; $gjorda++
}
if ($gjorda -eq 0) { Write-Host 'Inget att gora: allt till och med 1.2.12 finns redan.' } else {
    $kopia = Join-Path $env:TEMP ('spektro-fore-1.1.0-' + (Get-Date -Format 'yyyyMMdd-HHmmss'))
    $skrivna = 0; $skrivnaLista = @()
    foreach ($f in $nu.Keys) {
        if ($nu[$f] -eq $null -or (Las $f) -ceq $nu[$f]) { continue }
        $p = Join-Path $Rot $f
        if (Test-Path -LiteralPath $p) { $b = Join-Path $kopia $f; New-Item -ItemType Directory -Force (Split-Path $b) | Out-Null; Copy-Item -LiteralPath $p $b }
        New-Item -ItemType Directory -Force (Split-Path $p) | Out-Null
        [IO.File]::WriteAllText($p, $nu[$f], $utf8); $skrivna++; $skrivnaLista += $f
    }
    Write-Host "Steg gjorda: $gjorda (fran $fore till 1.2.12), filer skrivna: $skrivna"
    if (Test-Path $kopia) { Write-Host "Dina tidigare versioner: $kopia" }
}
if ($missade.Count) { Write-Host 'Steg i dina egna filer som inte gick (gor dem for hand fran sidan):'; $missade | ForEach-Object { Write-Host "  $_" } }
Set-Location $Rot
$OutputEncoding = $utf8; [Console]::OutputEncoding = $utf8; $env:PYTHONUTF8 = '1'; $env:MPLBACKEND = 'Agg'
$ErrorActionPreference = 'Continue'
$py = Join-Path $Rot '.venv\Scripts\python.exe'
if (-not (Test-Path $py)) { $py = Join-Path $Rot '.venv/bin/python' }
if (-not (Test-Path $py)) { $py = 'python' }
Write-Host "Python: $py"
if ($skrivnaLista -contains 'requirements.txt') {
    Write-Host 'requirements.txt andrades: installerar paketen'
    if (Get-Command uv -ErrorAction SilentlyContinue) { $env:VIRTUAL_ENV = Join-Path $Rot '.venv'; uv pip install -q -r requirements.txt 2>&1 | ForEach-Object { "  $_" } }
    else { & $py -m pip install -q -r requirements.txt 2>&1 | ForEach-Object { "  $_" } }
}
$ruffUt = @(& $py -m ruff check . --no-cache 2>&1 | ForEach-Object { "$_" }); $ruffKod = $LASTEXITCODE
$ruffUt | Select-Object -Last 3 | ForEach-Object { Write-Host $_ }
$pyUt = @(& $py -m pytest -q -rfE -p no:cacheprovider 2>&1 | ForEach-Object { "$_" }); $pyKod = $LASTEXITCODE
$pyUt | Where-Object { $_ -match '^(FAILED|ERROR)' } | ForEach-Object { Write-Host $_ }
Write-Host ($pyUt | Select-Object -Last 1)
$norm = { param($x) ($x -replace 'data/(\d{8}|\S{8})-(\d{6}|HHMMSS)(-\d+)?', 'data/MAPP' -replace 'residual: -?[0-9.]+e-1\d', 'residual: 0').TrimEnd() }
$facitFel = @(); $facitDiag = @()
foreach ($f in Get-ChildItem tests/kommandon -Filter 'testa_*.txt' | Sort-Object Name) {
    $facit = Join-Path $f.DirectoryName ($f.Name -replace '^testa_', 'facit_')
    if (-not (Test-Path $facit)) { continue }
    $rad = @(Get-Content $f.FullName -Encoding UTF8 | & $py -W error -m spectrometer.main 2>&1 | ForEach-Object { "$_" })
    $a = @($rad | ForEach-Object { & $norm $_ }); $c = @(Get-Content $facit -Encoding UTF8 | ForEach-Object { & $norm $_ })
    while ($a.Count -and $a[-1] -eq '') { $a = @($a[0..($a.Count - 2)]) }
    while ($c.Count -and $c[-1] -eq '') { $c = @($c[0..($c.Count - 2)]) }
    $lika = ($a.Count -eq $c.Count) -and (@(Compare-Object $a $c -SyncWindow 0).Count -eq 0)
    Write-Host ('{0,-14} {1}' -f $f.Name, $(if ($lika) { 'lika facit' } else { 'SKILJER fran facit' }))
    if (-not $lika) {
        $facitFel += $f.Name
        $facitDiag += "===== $($f.Name): rad for rad (programmet | facit)"
        $n = [Math]::Max($a.Count, $c.Count)
        for ($k = 0; $k -lt $n; $k++) { $x = if ($k -lt $a.Count) { $a[$k] } else { '<saknas>' }; $y = if ($k -lt $c.Count) { $c[$k] } else { '<saknas>' }; $facitDiag += ('{0} {1,4}  prog : {2}' -f $(if ($x -ceq $y) { ' ' } else { '!' }), ($k + 1), $x); if ($x -cne $y) { $facitDiag += ('       facit: {0}' -f $y) } }
    }
}
$allt = ($ruffKod -eq 0) -and ($pyKod -eq 0) -and ($facitFel.Count -eq 0) -and ($missade.Count -eq 0)
if ($allt) { Write-Host "KLART: allt till och med 1.2.12, ruff gron, pytest gron, facit lika. Committa nu." ; exit 0 }
# ---------- diagnos: allt som behovs for att se varfor, i en fil ----------
$ut = Join-Path ([Environment]::GetFolderPath('UserProfile')) ('Downloads\spektro-diagnos-1.1.0-1.2.12-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '.txt')
if (-not (Test-Path (Split-Path $ut))) { $ut = Join-Path $env:TEMP (Split-Path $ut -Leaf) }
$d = New-Object System.Collections.Generic.List[string]
function Rubrik([string]$rubrik) { $d.Add(''); $d.Add('#' * 100); $d.Add("# $rubrik"); $d.Add('#' * 100) }
Rubrik 'SAMMANFATTNING'
$d.Add("skript: spektro-1.1.0-1.2.12.ps1   tid: $(Get-Date -Format s)   rot: $Rot")
$d.Add("ruff slutkod: $ruffKod   pytest slutkod: $pyKod   facit som skiljer: $($facitFel -join ', ')")
$d.Add("lage fore: $fore   steg gjorda: $gjorda   egna filer: $(($egna.Keys | Sort-Object) -join ', ')")
$d.Add('missade steg:'); $missade | ForEach-Object { $d.Add("  $_") }
Rubrik 'MILJO'
$d.Add("PowerShell: $($PSVersionTable.PSVersion)  OS: $([Environment]::OSVersion.VersionString)  kultur: $([cultureinfo]::CurrentCulture.Name)")
$d.Add("python: $py"); & $py -c "import sys, platform; print(sys.version); print(platform.platform())" 2>&1 | ForEach-Object { $d.Add("$_") }
& $py -m pip list 2>&1 | ForEach-Object { $d.Add("$_") }
$d.Add("PYTEST_ADDOPTS=$env:PYTEST_ADDOPTS  PYTHONUTF8=$env:PYTHONUTF8")
Rubrik 'GIT'
foreach ($g in @('status --short', 'log --oneline -15', 'diff --stat', 'branch -vv', 'stash list')) { $d.Add("> git $g"); & git @($g -split ' ') 2>&1 | ForEach-Object { $d.Add("$_") } }
Rubrik 'FILERNA SOM STEGEN ROR: forvantad hash efter 1.2.12 mot din'
foreach ($f in ($lage['1.2.12'].Keys | Sort-Object)) { $hh = Hash (Las $f); $d.Add(('{0}  {1}  {2}' -f $(if ($hh -eq $lage['1.2.12'][$f]) { 'OK ' } elseif ($egna.ContainsKey($f)) { 'EGEN' } else { 'FEL' }), $f, $hh)) }
Rubrik 'RUFF (hela)'; $ruffUt | ForEach-Object { $d.Add($_) }
Rubrik 'PYTEST (hela, -rfE)'; $pyUt | ForEach-Object { $d.Add($_) }
if ($pyKod -ne 0) { Rubrik 'PYTEST IGEN, LANG TRACEBACK FOR DET SOM FALLER'; & $py -m pytest -q -x --tb=long -p no:cacheprovider 2>&1 | ForEach-Object { $d.Add("$_") } }
Rubrik 'FACIT'; $facitDiag | ForEach-Object { $d.Add($_) }
Rubrik 'MAPPTRADET (utan .git .venv __pycache__ caches data logs .pytest-tmp)'
$hoppa = '[\\/](\.git|\.venv|venv|__pycache__|\.pytest_cache|\.ruff_cache|\.mypy_cache|data|logs|\.pytest-tmp|node_modules)([\\/]|$)'
$alla = @(Get-ChildItem -LiteralPath $Rot -Recurse -Force -File -ErrorAction SilentlyContinue | Where-Object { $_.FullName.Substring($Rot.Length) -notmatch $hoppa } | Sort-Object FullName)
foreach ($x in $alla) { $d.Add(('{0,10}  {1}  {2}' -f $x.Length, $x.LastWriteTime.ToString('yyyy-MM-dd HH:mm:ss'), $x.FullName.Substring($Rot.Length + 1))) }
Rubrik 'INNEHALLET I VARJE TEXTFIL (cat)'
foreach ($x in $alla) {
    if ($x.Extension -notin '.py', '.txt', '.md', '.toml', '.csv', '.cfg', '.ini', '.json', '.yml', '.yaml', '.ps1', '.sh', '.gitignore', '.gitattributes', '') { continue }
    if ($x.Length -gt 300000 -or $x.Name -like 'spektro-1.*.ps1') { $d.Add("===== $($x.FullName.Substring($Rot.Length + 1))  ($($x.Length) byte, hoppad)"); continue }
    $d.Add("===== $($x.FullName.Substring($Rot.Length + 1))  ($($x.Length) byte, sha256 $(Hash (Las $x.FullName.Substring($Rot.Length + 1))))")
    $nr = 0; foreach ($l in ([IO.File]::ReadAllText($x.FullName) -split "`n")) { $nr++; $d.Add(('{0,5}| {1}' -f $nr, $l.TrimEnd("`r"))) }
}
[IO.File]::WriteAllLines($ut, $d, $utf8)
Write-Host ''
Write-Host "INTE KLART. Allt som behovs for att se varfor ligger i:`n  $ut`nDra in den filen i chatten."
exit 1

